sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {

    var enableNewDesign = gs.getProperty('x_hsb11_mss_c_proc.mssCustodyLinkTradesForBulk', false); //MSSCUSTODY-8813
    g_scratchpad.newDesignEnabled = false;

    //enable or disable the related tabs in Buk form for old design
    if (enableNewDesign.toString() == 'true') { //MSSCUSTODY-8813
        try {
            var gr = new GlideRecord("x_hsb11_mss_c_proc_mss_custody_trade");
            gr.addEncodedQuery("associated_bulk_idISNOTEMPTY^associated_bulk_id.sys_idSTARTSWITH" + current.getValue('sys_id'));
            gr.query();
            if (gr.next()) {
                g_scratchpad.newDesignEnabled = true;
            }

        } catch (ex) {
            gs.info('Error from Bulk File Uploadew Design - MSS - Bulk Redesign Display BR ' + ex);
        }
    }
    //enable or disable the related tabs in Buk form for old design

})(current, previous);
